mapper.update:
	UPDATE  /* isry.couns.constt.bbsonm.mapper.BbsonmListMapper.updateBbsonm : 실시간게시판 게시글수정 */
            AYE100 
	SET
	        BBSCTT_CN               =       #{BBSCTT_CN}
	    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
	    ,   LAST_MDFCN_DT           =       SYSDATE
	WHERE   1=1
	    AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
	    AND BBSCTT_TYPE_SE_CD       =       #{BBSCTT_TYPE_SE_CD}                /*게시글 유형구분 코드*/
